import{openModal,closeModal}from'./modalHelpers.min.js';export function setupUI(){const n=document.getElementById('navToggle'),e=document.getElementById('primary-nav');if(n&&e){n.addEventListener('click',()=>{const t=n.getAttribute('aria-expanded')==='true';n.setAttribute('aria-expanded',String(!t));e.classList.toggle('show')})}document.addEventListener('click',t=>{if(t.target.matches('.modal-close'))closeModal()});const o=document.getElementById('modal');if(o){o.addEventListener('click',t=>{if(t.target===o)closeModal()})}const theme=localStorage.getItem('theme');'dark'===theme&&document.documentElement.classList.add('dark')}export function renderGrid(n,e,o={}){n.innerHTML='';e.forEach(function(e){const t=document.createElement('article');t.className='card',t.tabIndex=0;const a=document.createElement('img');a.loading='lazy',a.alt=e.name+' image',a.src=e.image;const l=document.createElement('h3');l.textContent=e.name;const c=document.createElement('p');c.textContent=e.short;const m=document.createElement('p');m.innerHTML=`<strong>Price:</strong> ${e.price} • <strong>Category:</strong> ${e.category}`;const d=document.createElement('button');d.className='btn',d.textContent='Details',d.addEventListener('click',function(r){showDetails(e,r.currentTarget)}),t.addEventListener('keydown',function(r){'Enter'===r.key&&showDetails(e,t)}),t.appendChild(a),t.appendChild(l),t.appendChild(c),t.appendChild(m),t.appendChild(d),o.showFav&&(function(){const r=document.createElement('button');r.textContent=isFavorite(e.id)?'★':'☆',r.setAttribute('aria-pressed',String(isFavorite(e.id))),r.addEventListener('click',function(n){n.stopPropagation(),toggleFavorite(e.id,r)}),t.appendChild(r)})();n.appendChild(t)})}function showDetails(n,t){const e=document.getElementById('modal-title'),o=document.getElementById('modal-body');e.textContent=n.name,o.innerHTML=`
    <p>${n.long}</p>
    <ul>
      <li><strong>Price:</strong> ${n.price}</li>
      <li><strong>Category:</strong> ${n.category}</li>
      <li><strong>Stock:</strong> ${n.stock}</li>
    </ul>
  `,openModal(t||null)}function favorites(){try{return JSON.parse(localStorage.getItem('jj_favs')||'[]')}catch(n){return[]}}function isFavorite(n){return favorites().includes(n)}function toggleFavorite(n,t){const e=favorites(),o=e.indexOf(n);o>=0?e.splice(o,1):e.push(n),localStorage.setItem('jj_favs',JSON.stringify(e)),t&&(t.textContent=isFavorite(n)?'★':'☆',t.setAttribute('aria-pressed',String(isFavorite(n))))}